entries[230945] = { ["name"] = "Laterne des verlorenen Vrykul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Der Einsatz Eurer zentralen Klassenfähigkeit mit Abklingzeit erfüllt Euch mit der Wildheit von Vrykulseelen und erhöht Euren kritischen Trefferwert 8 Sek. lang um 3014 .\n\nAbhängig davon, wann Ihr zuletzt erfüllt wurdet, hält der Effekt bis zu 40 Sek. länger an.\nVerkaufspreis:" }
