entries[230985] = { ["name"] = "Aufkeimendes runenverziertes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein mächtiges Gefäß aus runenverzierten Lorenhallwappen, bereit zum Verzaubern.\"\nVerkaufspreis:" }
entries[230986] = { ["name"] = "Aufkeimendes vergoldetes Lorenhallwappen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein mächtiges Gefäß aus vergoldeten Lorenhallwappen, bereit zum Verzaubern.\"\nVerkaufspreis:" }
