entries[230990] = { ["name"] = "Schlüsselsteinkarte festlegen: Operation: Schleuse", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Legt Operation: Schleuse als Dungeon für einen mythischen Schlüsselstein fest.\nVerkaufspreis:" }
entries[231017] = { ["name"] = "Flügel des onyxfarbenen Monarchfalters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n\"Nur für die grimmigsten Feen gedacht.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[231019] = { ["name"] = "Hearthstone-Einladung", ["text"] = "Wird an Kriegsmeute gebunden\nDieser Gegenstand startet eine Quest.\n<Zum Lesen rechtsklicken>" }
entries[231021] = { ["name"] = "Importiertes Gebräue", ["text"] = "Questgegenstand\n80 ( 80)\n\"Ein Kasten mit verschiedenen Gebräuen aus ganz Azeroth.\"" }
entries[231022] = { ["name"] = "Schrottteile", ["text"] = "Questgegenstand\n\"Nützliche Teile Goblinmetallschrott von allerlei Goblinmaschinen.\"" }
entries[231064] = { ["name"] = "Wegwerfverkleidung für Gangster", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verkleidet Euch als echten Halunken aus Lorenhall, damit die Einheimischen Euch fürchten und 20 Min. lang in Ruhe lassen. Kann nur in Lorenhall eingesetzt werden. (1 Stunde Abklingzeit)" }
entries[231089] = { ["name"] = "Korrespondenz von Zirdo", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Brief von Zirdo, in dem er Pamsys Beteiligung an der Öffnung der Wand beschreibt, die die Aufmerksamkeit von Gallywix' Schwarzblutabbau erregt hat. Beweist, dass Zirdo Pamsy verraten hat, was zum Angriff von Gozzic auf ihre Ingenieure geführt hat.\"" }
entries[231099] = { ["name"] = "Umschnallrakete", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Anweisungen\nSchritt 1: Rakete auf den Rücken schnallen\nSchritt 2: Rakete zünden\nSchritt 3: Abheben\n\nKann nur in Lorenhall benutzt werden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[231116] = { ["name"] = "Verfluchter Piratenschädel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke]\n+ 565 Lebensdiebstahl\nAnlegen: Eure Nahkampfangriffe haben eine Chance, eine Blutnova aufzurühren, die 5 Gegnern innerhalb von 5 Metern um Euch 8 Sek. lang pro Sekunde 15514 Schattenschaden zufügt.\nVerkaufspreis:" }
entries[231117] = { ["name"] = "Kugel des Nachtflutwellenbeugers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Distanzzauber und -fähigkeiten haben eine Chance, einen Batzen Wasser auf einen Gegner zu schleudern, der diesem sowie vier weiteren Gegnern innerhalb von 7 Metern um ihn 76721 Frostschaden zufügt.\nVerkaufspreis:" }
entries[231118] = { ["name"] = "Sturmgebundene Rune des Runenmagiers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Alle 6 Sek. im Kampf wird die Rune überladen und trifft einen Gegner in der Nähe mit einem Blitz, der 55239 Naturschaden verursacht.\n\nDieser Effekt wird sofort ausgelöst, wenn eine Kreatur zum ersten Mal getroffen wird.\nVerkaufspreis:" }
