entries[231163] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[231164] = { ["name"] = "Goblingreifkette", ["text"] = "Questgegenstand\nBenutzen: Wirft den Greifhaken nach einem Schrotternter innerhalb von 40 Metern und zieht ihn zu Euch. (5 Sek. Abklingzeit)\n\"So holt man fliegende Roboter aus der Luft. Mit Haken, Schnur und Angelblei.\"" }
entries[231173] = { ["name"] = "Magnetomech des Schrottmaestros", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gut dafür geeignet, Müll in rollbare Ballen zu pressen. Laut Schrottmaestroapokryphen, sollen sich daraus eigene Welten entwickeln, wenn sie nur groß genug werden.\"\nErfolg:\nRuhm des Schlachtzüglers der Befreiung von Lorenhall\nKategorie:\nDungeons & Schlachtzüge" }
entries[231263] = { ["name"] = "Der Fall der abergläubischen und hungrigen Piraten", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Notizen, in denen meine Abenteuer aufgeführt werden, wie ich den Bukanieren von Beutebucht in Zeiten der Not zu Hilfe kam.\"\n<Zum Lesen rechtsklicken>" }
