entries[231766] = { ["name"] = "Horn von Hammerfall", ["text"] = "Questgegenstand\nBenutzen: Blast dieses Horn am Eingang eines Gebäudes von Hammerfall, um einen Schamanen zu rufen, der die Flammen löscht. (2 Sek. Abklingzeit)\n\"Ein Horn der Mag'har, das als Signal der Vorhut verwendet wurde.\"" }
entries[231767] = { ["name"] = "Verzaubertes verwittertes Astralwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+100 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[231768] = { ["name"] = "Verzaubertes vergoldetes Astralwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+20 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken des Sternenlichts hergestellt werden.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[231769] = { ["name"] = "Verzaubertes runenverziertes Astralwappen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+10 Rezeptschwierigkeit\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken des Sternenlichts hergestellt werden.\n\"Ein magisches Wappen, das hergestellte Ausrüstung mit höherer Macht erfüllt. Ist bei Syenite in Dornogal erhältlich.\"\nVerkaufspreis:" }
entries[231773] = { ["name"] = "Fundbürotruhe", ["text"] = "Questgegenstand\nBenutzen: Packt die Truhe aus, um alle fünf enthaltenen Gegenstände zu bekommen.\n\"Eine Truhe mit Fundsachen, die Alyx wieder ihren rechtmäßigen Besitzern zuführen will.\"" }
entries[231786] = { ["name"] = "Tagebuch eines Fiddlers", ["text"] = "Questgegenstand\n\"Zusammenhangloses Gekritzel, das die fünf skurrilen Reisen eines Ho-zen zur Insel dokumentieren.\"" }
entries[231788] = { ["name"] = "Lieder der Sirene", ["text"] = "Questgegenstand\n\"Zweiundzwanzig Seiten, die mit sich wiederholenden, nicht entzifferbaren Worten vollgeschrieben sind.\"" }
entries[231791] = { ["name"] = "Siegel des Erlösers", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Hebt das Siegel des Erlösers, um die Verderbnis des Schattens zu vertreiben.\n\"Alt, aber in makellosem Zustand.\"" }
entries[231802] = { ["name"] = "Probenbericht von Aschenwind & Co.", ["text"] = "Questgegenstand\n\"Belegt die rücksichtlose Gier, die Aschenwind & Co. dazu veranlasst hat, Sicherheitsbedenken zu ignorieren.\"" }
entries[231804] = { ["name"] = "Spielfigur", ["text"] = "Questgegenstand\n\"Eine Sammlung verschiedener Spielfiguren.\"" }
entries[231808] = { ["name"] = "Uralte Schatznotizen", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Die Notizen wurden in unsauberer Handschrift verfasst und sehen nicht wirklich 'uralt' aus.\"\n<Zum Lesen rechtsklicken>" }
entries[231809] = { ["name"] = "Erster Maat Dat-Dats Schlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Schlüssel zu Dat-Dats privatem Lesematerial.\"\nVerkaufspreis:" }
entries[231812] = { ["name"] = "Poesie der Ho-zen", ["text"] = "Questgegenstand\n\"Enthält die Gedichte \"Frohe Schweife\", \"Uukie frisst Ratten\" und \"Der dunkle Abgrund\".\"" }
entries[231813] = { ["name"] = "Manifest der Sireneninsel", ["text"] = "Questgegenstand\n\"Zahlreiche Bemühungen, die Ausbeute der Insel ungerecht aufzuteilen.\"" }
entries[231818] = { ["name"] = "Umschlingende Krone der Tiefe", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n377 Rüstung\n+578 Intelligenz\n+2.008 Ausdauer\nErhöht Eure kritische Trefferwertung um + 296.\nErhöht Eure Tempowertung um + 550.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
