entries[231820] = { ["name"] = "Festballons", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig" }
entries[231821] = { ["name"] = "Behelfsmäßiger Sprengstoff", ["text"] = "Questgegenstand\nBenutzen: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 Sek..\nInflicts 4 Fire damage to enemies within 5 yards of the impact. (5 Sek. Abklingzeit)\n\"Dieser behelfsmäßige Sprengstoff sollte genügen. Eine Explosion ist schließlich eine Explosion.\"" }
