entries[231831] = { ["name"] = "Ve'naris Paket", ["text"] = "Questgegenstand\n\"Das Gerät gibt ein leises aber stetes Trillern von sich.\"" }
entries[231832] = { ["name"] = "Bronzedrachenfeiertitel: Schürfer des Geschmolzenen Kerns", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt den Titel \"Schürfer des Geschmolzenen Kerns\"." }
entries[231833] = { ["name"] = "Bronzedrachenfeiertitel: Absolvent von Karazhan", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt den Titel \"Absolvent von Karazhan\"." }
entries[231839] = { ["name"] = "Langbogen des Spurensuchers", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n9 - 13 Schaden Geschwindigkeit 3.00\n(3.7 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 85 / 85\nKlassen: Jäger\nVerkaufspreis:" }
entries[231840] = { ["name"] = "Armbrust des Spurensuchers", ["text"] = "Wird beim Aufheben gebunden\nDistanz Armbrust\n8 - 13 Schaden Geschwindigkeit 3.00\n(3.5 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 85 / 85\nKlassen: Jäger\nVerkaufspreis:" }
entries[231878] = { ["name"] = "Beweisartikel", ["text"] = "Questgegenstand\n\"Diese erlesenen Gegenstände gehören zu den verschiedenen menschlichen Fraktionen, die die Rote Dämmerung bilden.\"" }
entries[231879] = { ["name"] = "Kopftuch der Defias", ["text"] = "Questgegenstand\n\"Beweisartikel. Das unverkennbar rote Kopftuch der Bruderschaft der Defias. Alt und etwas verblasst, aber immer noch mit kräftiger Farbe.\"" }
entries[231880] = { ["name"] = "Orangefarbenes Kopftuch", ["text"] = "Questgegenstand\n\"Beweisartikel. Dieses orangefarbene Kopftuch, das oft von denen getragen wird, die mit dem Syndikat in Verbindung stehen, hebt sich vom Rot aus Stromgarde, der Defias und des Scharlachroten Kreuzzugs ab.\"" }
entries[231881] = { ["name"] = "Emblem des Syndikats", ["text"] = "Questgegenstand\n\"Beweisartikel. Euch ist zu Ohren gekommen, dass Schurken diese aus Kleidungstaschen gestohlen haben, wobei das deutlich einfacher ist, wenn der Besitzer das Zeitliche gesegnet hat.\"" }
entries[231883] = { ["name"] = "Wappenrock des Scharlachroten Kreuzzugs", ["text"] = "Questgegenstand\n\"Beweisartikel. Dieser Wappenrock scheint gar nicht so selten zu sein, wie andere es haben klingen lassen.\"" }
entries[231884] = { ["name"] = "Wappenrock von Stromgarde", ["text"] = "Questgegenstand\n\"Beweisartikel. Ein Wappenrock der Soldaten von Stromgarde. Alt und zerlumpt, scheinbar wurde er nicht gut gepflegt.\"" }
entries[231886] = { ["name"] = "Verschimmelte Feierkiste", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[231888] = { ["name"] = "Verschimmelte Lösegeldforderung", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>" }
entries[231889] = { ["name"] = "Quasineue mechanische Teile", ["text"] = "Questgegenstand\n\"Brauchbare Teile, wenn Ihr nichts gegen ein paar Macken und den Schießpulvergeruch einzuwenden habt. Verleiht allem einen gewissen Charakter, nicht wahr?\"" }
entries[231893] = { ["name"] = "Schmierfettreste", ["text"] = "Questgegenstand\n\"Reste von den Tiefenreitern. Sicher zu etwas zu gebrauchen!\"" }
entries[231894] = { ["name"] = "Nützlicher Müll", ["text"] = "Questgegenstand" }
entries[231895] = { ["name"] = "Alkoholfreie Cocktailreste", ["text"] = "Questgegenstand\n\"Darin ist immer noch ein kleines Schirmchen!\"" }
entries[231896] = { ["name"] = "Ungenutztes Glas", ["text"] = "Questgegenstand\n\"Wollten die was einmachen?\"" }
entries[231897] = { ["name"] = "Verrostete Münze", ["text"] = "Questgegenstand\n\"Besitzt keinen Geldwert. Ist aber gut für chemische Reaktionen geeignet.\"" }
entries[231898] = { ["name"] = "Industrieller Schminkeentferner", ["text"] = "Questgegenstand\n\"Starkes Zeug. Kann sich durch den Boden eines Mülleimers fressen.\"" }
entries[231899] = { ["name"] = "Müll", ["text"] = "\"Das ist nur Müll.\"\nVerkaufspreis:" }
entries[231900] = { ["name"] = "Trankprobe", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Probe! (4 Sek. Abklingzeit)\n\"Gratisprobe! Wird an jeden potenziellen Kunden ausgeschenkt!\"" }
entries[231905] = { ["name"] = "Briefe", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nBenutzen: Verteilt die Briefe an Besucher außerhalb der Höhlen der Zeit. (3 Sek. Abklingzeit)" }
