entries[232374] = { ["name"] = "Schmalzige Würstchen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 5637 * 20 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Ellenlange Würste aus fettreichen Verschnitten und köstlichen Kräutern und Gewürzen. Gebrüht und anschließend gegrillt. Vollgepackt mit Geschmack.\"\nVerkaufspreis:" }
entries[232375] = { ["name"] = "Mondbrot", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 1128 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Eine große Version der kleinen halbmondförmigen Laibe, die von Gläubigen von Elune als rituelle Opfergaben dargeboten werden.\"\nVerkaufspreis:" }
entries[232376] = { ["name"] = "Kirschbomben", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 56250 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Mit hochprozentigem Kornbrand aufgefüllt und ein Jahr und einen Tag lang in einem Einlegegefäß vergraben. Diese Kirschen haben es faustdick hinter den Ohren.\"\nVerkaufspreis:" }
entries[232377] = { ["name"] = "Papa Donnerbräus Hustensirup", ["text"] = "Benutzen: Dieses Gebräu lässt den Trinkenden für 5 Min. in heftige Wut verfallen. Starker Alkohol.\n\"Ein Schluck am Tag, auf dem Friedhof kein Sarg. Wird heiß mit zwei Zimtstangen serviert.\"\nVerkaufspreis:" }
entries[232378] = { ["name"] = "Jenkins' Brathähnchen ohne Schnickschnack", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"\"Die doppelte Menge Kräuter, aber keine Gewürze. Und doch einfach unwiderstehlich!\" - Mama Jenkins\"\nVerkaufspreis:" }
