entries[232526] = { ["name"] = "Spieloplatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Streitkolben\n7,750 - 9,965 Schaden Geschwindigkeit 3.60\n(2,460 Schaden pro Sekunde)\n+3.269 [Beweglichkeit oder Stärke]\n+19.463 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, einen zufälligen Eurer Sekundärwerte 15 Sek. lang um [Quellwert] bis [Quellwert] zu erhöhen.\nBenutzen: Schummelt, um Euren höchsten Sekundärwert sofort für 15 Sek. um [Quellwert] zu erhöhen. Außerhalb des Kampfes werdet Ihr stattdessen für das Zauberwirken rekonfiguriert. (2 Min Abklingzeit)\nBezwingt den Einarmigen Banditen in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\n\"Der weise Goblin schafft sich sein eigenes Glück.\"\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[232527] = { ["name"] = "Glyphe 'Traditionelle Aszendenz'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Aszendenz-Transformationen verkörpern ihre traditionellen Gestalten.\nVerkaufspreis:" }
entries[232531] = { ["name"] = "Knirschi", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[232535] = { ["name"] = "Technik: Vertrag: Die Kartelle von Lorenhall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Vertrag: Die Kartelle von Lorenhall herstellt.\nBenötigt Inschriftenkunde von Khaz Algar (35)\nBenötigt Inschriftenkunde von Khaz Algar und Ruhmrang 5 bei den Kartellen von Lorenhall.\nVerkaufspreis:" }
entries[232541] = { ["name"] = "Improvisierter Zephyriumschrittmacher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.508 [Beweglichkeit oder Stärke]\nAnlegen: Funktioniert eine Zephyriumladung um und treibt Eure Herzfrequenz nach oben, wodurch Eure erste Fähigkeit alle 60 Sek. 'Explosives Adrenalin' auslöst, was 15 Sek. lang Euren kritischen Trefferwert um 2624 erhöht.\n\nWährend der Explosion bewirken kritische Treffer, dass Ihr erneut explodiert, wodurch sich die Dauer bis zu 15-mal um 1 Sek. verlängert.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt Operation: Schleuse in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\n\"Das ist verrückt genug, dass es klappen könnte...\"\nVerkaufspreis:" }
entries[232542] = { ["name"] = "Sanikopter der Düsternisverschmolzenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.508 Intelligenz\nBenutzen: Weist den Sanikopter an, sich an Euer Ziel zu heften. Dadurch wird beim Ziel 155184 Schaden absorbiert und seine Vielseitigkeit wird 15 Sek. lang um 1375 erhöht.\n\nSolange der Sanikopter an das Ziel geheftet bleibt, besteht bei Euren Heilzaubern die Chance, den Sanikopter wieder aufzutanken und dem Ziel diese Boni erneut zu gewähren. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt Operation: Schleuse in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[232543] = { ["name"] = "Schallender Ritualmatsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 1.426 Vielseitigkeit\nBenutzen: Werdet 'Schlammgetragen', wodurch Ihr 7088217 Schaden absorbiert und im Verlauf von 10 Sek. regelmäßig ( 69870 * 10 / 2) Naturschaden verursacht, der zwischen Gegnern in der Nähe aufgeteilt wird.\n\nWenn Ihr regelmäßigen Schaden erleidet, verschmilzt dieser zu stinkendem Schlamm, der das Ritual weiter nährt und die Abklingzeit um [2][2.0] Sek. verringert. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt Operation: Schleuse in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\n\"Fürchtet den alten Matsch.\"\nVerkaufspreis:" }
entries[232545] = { ["name"] = "Gigaschocks Schockkappe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.508 Intelligenz\nAnlegen: Alle 6 Sek. versetzt Ihr Eurem Ziel und 1 Gegner in der Nähe einen Schock und fügt ihnen ( 34365 * 1 ) Naturschaden zu.\n\nDurch den Einsatz von 30 Zaubern werdet Ihr für 15 Sek. 'Turbogeladen', was die Häufigkeit Eurer Schocks verdoppelt und sie zu Gigaschocks macht, die stattdessen ( 34365 * 3 * 1 ) Naturschaden verursachen. (500ms Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt Operation: Schleuse in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[232546] = { ["name"] = "K.U.-J.0.s Flammendüsen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+3.508 [Beweglichkeit oder Stärke]\nBenutzen: Kanalisiert, um 2 Sek. lang Flammen auszustoßen, die [Quellwert] Feuerschaden verursachen, die auf Gegner in der Nähe aufgeteilt werden.\n\nMechanische Gegner werden 'Supererhitzt', wodurch sie 90352 zusätzlichen Feuerschaden erleiden, wenn sie von Eurer nächsten Schadensfähigkeit getroffen werden. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:", ["unresolvedValues"] = true }
