entries[232617] = { ["name"] = "Teufelsfledermaus des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In den Höhlen des Schlachtfelds erweckt und bis an die Zähne gepanzert.\"\nErfolg:\nGladiator: Saison 3 von The War Within\nKategorie:\nSpieler gegen Spieler" }
entries[232618] = { ["name"] = "Geringes Artefakt der K'areshi", ["text"] = "Questgegenstand\n\"Was hat Ve'nari bloß mit diesen Artefakten vor?\"" }
entries[232619] = { ["name"] = "Gary der Goldfisch", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein wenig schleimig, aber sonst noch in Ordnung.\"" }
entries[232620] = { ["name"] = "Medium des geachteten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3.486 Intelligenz\n+5.458 Ausdauer\n+ 494 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 266.\nSchließt den Erfolg \"Geachtete Waffen der Eroberung\" ab, um zusätzliche Waffen kaufen zu können.\nVerkaufspreis:" }
entries[232622] = { ["name"] = "Glyphe 'Energetische Aszendenz'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Aszendenz-Transformationen verkörpern energetische Gestalten und entfesseln ihre Macht.\nVerkaufspreis:" }
entries[232624] = { ["name"] = "Zeitige Summbiene", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Pünktlich wie eh und je brausen diese Summbienen durch die Zeit, sammeln die fehlgeleiteten Sande der Zeit und bringen sie sicher wieder zu den Zeitwegen zurück.\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000" }
entries[232625] = { ["name"] = "Artefakt der Ödnisbewohner", ["text"] = "Questgegenstand\n\"Ein kleiner Edelstein an einer zarten Kette.\"" }
entries[232626] = { ["name"] = "Artefakt der Ödnisbewohner", ["text"] = "Questgegenstand\n\"Sorgfältig versiegelte Schriftrollen.\"" }
entries[232627] = { ["name"] = "Artefakt der Ödnisbewohner", ["text"] = "Questgegenstand\n\"Ein seltsames Gerät mit unbekanntem Zweck.\"" }
entries[232628] = { ["name"] = "Artefakt der Ödnisbewohner", ["text"] = "Questgegenstand\n\"Für die Ödnisbewohner sind diese Gegenstände unbezahlbar. Für einen Sammler ist der Wert schon eher verhandelbar.\"" }
entries[232629] = { ["name"] = "Destilliertes Wissen der Zeitwege", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Erhöht die durch das Töten von Monstern und das Abschließen von Quests erhaltene Erfahrung um 5%.\n\nDer Abschluss eines Zeitwanderungsdungeons verstärkt den Effekt und setzt die Dauer zurück.\n\nBeim Erreichen von 4 Anwendungen erfolgt eine Umwandlung zu ' Meister der Zeitwege ', was den Effekt auf 30% erhöht." }
entries[232630] = { ["name"] = "Importregister der Xy", ["text"] = "Questgegenstand\n\"Die neueste Version des Xy-Importregisters. Enthält Informationen über die täglichen Geschäftsvorgänge.\"" }
