entries[232639] = { ["name"] = "Thrayir, Augen der Sirene", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In seiner Verzweiflung und Wut beschwor Thrayir einen Sturm, der das Land verwüstete und Cyrces Feinde vernichtete. Nach fast zehntausend Jahren tobt das Meereszornunwetter weiter als Widerhall seiner Macht.\"\nZone:\nSireneninsel" }
entries[232643] = { ["name"] = "Geheimnisvolles zerlumptes Tagebuch", ["text"] = "Questgegenstand\n\"Ein mit Flecken bedecktes und zerlumptes Tagebuch, in dem anscheinend ein Großteil der Seiten fehlt.\"" }
entries[232644] = { ["name"] = "Mittlerverkleidungsnadel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nehmt das Aussehen eines Mitarbeiters von Xy Importe an.\n\"Eine unscheinbare Anstecknadel aus Metall mit einem Hauch gut eingeübter Illusionsmagie.\"" }
entries[232645] = { ["name"] = "Himmelsbeschuss", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Offensiv" }
entries[232646] = { ["name"] = "Speer des Wurzelverteidigers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[232647] = { ["name"] = "Schild des Wurzelverteidigers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[232651] = { ["name"] = "Verblasste Tagebuchseite", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Die Seite ist kaum leserlich und stark verwittert. Es scheint lange den Elementen ausgesetzt gewesen zu sein.\"" }
entries[232653] = { ["name"] = "Gewagtes Geschenk", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein Geschenk beschwören oder wieder freigeben.\n80 ( 80)" }
