entries[232804] = { ["name"] = "Capos geschmolzener Schlagring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nEinhändig Faustwaffe\n3,985 - 5,676 Schaden Geschwindigkeit 2.60\n(1,858 Schaden pro Sekunde)\n+1.634 [Beweglichkeit oder Stärke]\n+9.732 Ausdauer\nHaltbarkeit 80 / 80\nAnlegen: Ihr erhaltet eine hohe Chance, Euren Angriffen einen feurigen Aufwärtshaken folgen zu lassen, der Eurem Ziel ( 256974 * 1 ) Feuerschaden zufügt. Geschmolzenes Gold wird versprüht, das allen Gegnern in der Nähe im Verlauf von 5 Sek. ( 14276 * 1 * 5) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\nBezwingt Mug'Zee in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad 'Mythisch'.\nVerkaufspreis:" }
entries[232805] = { ["name"] = "Spieloplatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Streitkolben\n3,875 - 4,983 Schaden Geschwindigkeit 3.60\n(1,230 Schaden pro Sekunde)\n+14.533 Intelligenz\n+19.463 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, einen zufälligen Eurer Sekundärwerte 15 Sek. lang um [Quellwert] bis [Quellwert] zu erhöhen.\nBenutzen: Schummelt, um Euren höchsten Sekundärwert sofort für 15 Sek. um [Quellwert] zu erhöhen. Außerhalb des Kampfes werdet Ihr stattdessen für den Nahkampf rekonfiguriert. (2 Min Abklingzeit)\n\"Der weise Goblin schafft sich sein eigenes Glück.\"\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[232806] = { ["name"] = "Minitorq", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Minitorq beschwört, dessen Vater Leuchtendos Vater VOLL VERPRÜGELN konnte.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ruhmrang 9 beim Garbagio Treueclub." }
