entries[232981] = { ["name"] = "GNZ Luftmeister 9000", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Installiert diesen Motor, um die Höchstgeschwindigkeit Eures 99-G-Genickbrechers auf Kosten der Beschleunigung zu steigern.\nBenötigt Ruhmrang 19 bei den Kartellen von Lorenhall.\n\"Dieser Block hat Zylinder mit 80-mm-Bohrungen und liefert 35.000 Pferdestärken.\"" }
entries[232982] = { ["name"] = "Pozziks Standardmodell", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Installiert diesen Motor, um die Beschleunigung Eures 99-G-Genickbrechers auf Kosten der Höchstgeschwindigkeit zu steigern.\n\"Als die Illusionenrennbahn während des Kataklysmus zerstört wurde, brauchte Pozzik ein neues Plätzchen, um seine Fähigkeiten zu schulen.Lorenhall stellte sich als fruchtbarer Boden für eine automatische Revolution heraus.\"" }
entries[232983] = { ["name"] = "Kesseldampf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Installiert diesen Turbo, um Eurem 99-G-Genickbrecher einen Geschwindigkeitsschub zu verleihen. Dieser Turbo besitzt eine höhere Höchstgeschwindigkeit auf Kosten der Effizienz.\n\"Bei der Verbrennung als Treibstoff soll er hundert Mal mehr Energie erzeugen als das gute alte Nitro.\"\nVerkaufspreis:" }
entries[232984] = { ["name"] = "Handbremse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Installiert diesen Turbo, um Eurem 99-G-Genickbrecher einen Geschwindigkeitsschub zu verleihen. Dieser Turbo besitzt eine höhere Effizienz auf Kosten der Höchstgeschwindigkeit.\n\"Nichts funktioniert besser als die gute alte Ellenbogenschmiere.\"\nVerkaufspreis:" }
