entries[232991] = { ["name"] = "Die Lied des Wellenbrechers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört die Lied des Wellenbrechers oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es kommt selten vor, dass ein Matrose genau das Monster, das ihn zum Sterben zurückgelassen hat, an den Bug seines Schiffes schnitzt. Wir sind ein mickriger und gotteslästerlicher Haufen. Dass einer von uns sich herablässt, eine solche Kreatur zu würdigen, grenzt an Wahnsinn.\"\nZone:\nSireneninsel\nErfolg:\nEine denkwürdige Insel" }
entries[232992] = { ["name"] = "Große Käferteile", ["text"] = "Questgegenstand\nBenutzen: Teilt ein großes Käferteil in 5 kleinere Käferteile. Sehr schade, dass Rhubarn nicht spezifiziert hat, wie groß die Käferteile sein müssen. So ein Pech aber auch.\n\"Eine sehr fleischige und schleimige Portion Käferfleisch.\"" }
entries[233006] = { ["name"] = "Behälter mit hochprofitablem Schlick", ["text"] = "\"Das Zeug riecht merkwürdig und schwappt im Behälter hin und her. Lasst ihn lieber nicht fallen.\"" }
entries[233007] = { ["name"] = "Kiste mit mäßig profitablem Schlick", ["text"] = "\"Fühlt sich gar nicht so schwer an, hat aber doch schon einiges an Gewicht, wenn man es schleppen muss. Und so besteht die Last fort.\"" }
entries[233008] = { ["name"] = "Schachtel mit leicht profitablem Schlick", ["text"] = "\"Diese kleinen Mengen wirken nicht nach viel, aber Kleinvieh macht auch Mist.\"" }
entries[233009] = { ["name"] = "Feuerblütenpollen", ["text"] = "Questgegenstand\n\"Dieser Pollen fühlt sich ungewöhnlich warm an.\"" }
entries[233013] = { ["name"] = "Kohlekeks", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 25 Sek. ( 472500 / 5 * 25) Gesundheit und ( 630000 / 5 * 25) Mana wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[233014] = { ["name"] = "Schatzkiste der Bronzedrachenfeier", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Materialien zur Aufwertung von Ausrüstung, Gold und vielem mehr.Die erste wöchentliche Truhe, die Ihr Euch jede Woche verdient, enthält einen Ausrüstungsgegenstand des Champions aus den Schwarzfelstiefen und einen restaurierten Kastenschlüssel. Nachfolgende Truhen enthalten einen Ausrüstungsgegenstand des Veteranen.\"\n<Zum Öffnen rechtsklicken>" }
entries[233018] = { ["name"] = "Essenzsammler", ["text"] = "Questgegenstand\n\"Dicke Metallstäbe wölben sich um einen knisternden violetten Energiekern. Der Sammler vibriert, pulsiert und sendet ein elektrisches Kribbeln Euren Arm hinauf.\"" }
entries[233019] = { ["name"] = "Feger der Himmelshexe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren magischen Besen oder gibt ihn wieder frei! Dieser Besen passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es gibt nach oben keine Grenzen, wenn man auf diesem magischen Besen der Reihe \"Bewegung durch Erregung\" sitzt.\"\nWoW-Shop" }
entries[233020] = { ["name"] = "Feger der Zwielichthexe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren magischen Besen oder gibt ihn wieder frei! Dieser Besen passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein dunklerer Look für die Reitbesen der \"Bewegung durch Erregung\"-Reihe. Fans dieser Farbe wissen einfach, dass er zu jeder Tageszeit umwerfend aussieht.\"\nWoW-Shop" }
entries[233021] = { ["name"] = "Greifgreifer 9000", ["text"] = "\"Dieses Gerät ermöglicht es Euch, Goblins und Sprengstoffe aus der Ferne zu greifen!\"" }
entries[233022] = { ["name"] = "Technik: Vantusrune: Befreiung von Lorenhall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Befreiung von Lorenhall herstellt.\nBenötigt Inschriftenkunde von Khaz Algar (35)\nBenötigt Inschriftenkunde von Khaz Algar und Ruhmrang 5 bei den Kartellen von Lorenhall.\nVerkaufspreis:" }
entries[233023] = { ["name"] = "Feger von Silbermond", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren magischen Besen oder gibt ihn wieder frei! Dieser Besen passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Silbermonds Farbschema für die \"Bewegung durch Erregung\" war in ganz Azeroth ein Erfolg.\"\nHandelsposten" }
entries[233025] = { ["name"] = "Riesiger Haufen Goldmünzen", ["text"] = "\"Was für eine Ausbeute! Wer hätte gedacht, dass ein paar Neruber so viel Gold rumschleppen?\"" }
entries[233026] = { ["name"] = "Johnnys Anteil der Beute", ["text"] = "\"Das könnte Johnnys Reparaturkosten begleichen.\"" }
entries[233027] = { ["name"] = "Geliebtes Quietschspielzeug", ["text"] = "Wird beim Aufheben gebunden\n\"Mit mehreren Staubschichten bedeckt, quietscht dieses Spielzeug trotzdem noch leicht, wenn es zusammengedrückt wird.\"" }
entries[233028] = { ["name"] = "Flammenwerfer", ["text"] = "Questgegenstand\nBenutzen: Das Feuer des Mittlers brennt in mehreren Energiespektren zugleich. (10 Sek. Abklingzeit)\n\"Manchmal ist Feuer die Antwort.\"" }
